insert  into `travel_guide`(`id`,`title`,`city`,`summary`,`content`,`view_count`,`created_at`,`updated_at`,`author_id`) values (1,'北京两日文化游','北京','1200元，北京5日游','好玩好玩，好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩好玩',4,'2026-07-07 03:54:55.238849','2026-07-07 03:54:55.238863',4),(2,'北京2日城市漫步攻略','北京','北京2日城市漫步路线，节奏均衡，人均预算约 300 元，适合参考 红剧场、两湖大瀑布。','【行程概览】\n这是一条围绕 北京 设计的 2 日旅游攻略，整体节奏偏均衡，适合喜欢城市漫步的游客。\n\n【推荐景点】\n红剧场、两湖大瀑布。\n\n【路线安排】\n第 1 天建议先游览城市核心区域，把交通时间控制在 30 分钟以内。\n第 2 天可以安排特色街区和高评分景点，下午留出休息时间。\n如果时间充足，后续行程可以增加周边景点或夜游活动。\n\n【预算建议】\n人均预算约 300 元，主要包括交通、门票、餐饮和少量伴手礼。\n\n【交通建议】\n雨天建议把室外景点替换成博物馆、展馆或商圈。\n\n【餐饮建议】\n如果预算有限，可以把下午茶换成便利店补给。\n\n【避坑提醒】\n节假日要提前预约门票，并预留安检和排队时间。',949,'2026-07-07 03:58:06.558633','2026-07-07 03:58:06.558633',11),(3,'崇州4日亲子慢游攻略','崇州','崇州4日亲子慢游路线，节奏轻松，人均预算约 1200 元，适合参考 板桥红枫。','【行程概览】\n这是一条围绕 崇州 设计的 4 日旅游攻略，整体节奏偏轻松，适合喜欢亲子慢游的游客。\n\n【推荐景点】\n板桥红枫。\n\n【路线安排】\n第 1 天建议先游览城市核心区域，把交通时间控制在 30 分钟以内。\n第 2 天可以安排特色街区和高评分景点，下午留出休息时间。\n如果时间充足，后续行程可以增加周边景点或夜游活动。\n\n【预算建议】\n人均预算约 1200 元，主要包括交通、门票、餐饮和少量伴手礼。\n\n【交通建议】\n雨天建议把室外景点替换成博物馆、展馆或商圈。\n\n【餐饮建议】\n晚餐建议提前收藏本地小吃街，避免临时排队。\n\n【避坑提醒】\n不要把距离很远的景点硬塞进同一天，体验会明显下降。',11,'2026-07-07 03:58:07.101954','2026-07-07 03:58:07.101954',11),(4,'万源2日夜游路线攻略','万源','万源2日夜游路线路线，节奏轻松，人均预算约 800 元，适合参考 鑫达国际养生谷森林温泉、宜良68道拐、不老潭。','【行程概览】\n这是一条围绕 万源 设计的 2 日旅游攻略，整体节奏偏轻松，适合喜欢夜游路线的游客。\n\n【推荐景点】\n鑫达国际养生谷森林温泉、宜良68道拐、不老潭。\n\n【路线安排】\n第 1 天建议先游览城市核心区域，把交通时间控制在 30 分钟以内。\n第 2 天可以安排特色街区和高评分景点，下午留出休息时间。\n如果时间充足，后续行程可以增加周边景点或夜游活动。\n\n【预算建议】\n人均预算约 800 元，主要包括交通、门票、餐饮和少量伴手礼。\n\n【交通建议】\n如果同行人数较多，可以把远距离景点安排在同一天集中打车。\n\n【餐饮建议】\n带孩子出行时建议准备少量零食和水，减少临时采购。\n\n【避坑提醒】\n节假日要提前预约门票，并预留安检和排队时间。',629,'2026-07-07 03:58:07.110948','2026-07-07 03:58:07.110948',11),(5,'成都1日夜游路线攻略','成都','成都1日夜游路线路线，节奏紧凑，人均预算约 500 元，适合参考 成都市天府美术馆、小猪佩奇欢乐乐园(成都店)、资阳市博物馆。','【行程概览】\n这是一条围绕 成都 设计的 1 日旅游攻略，整体节奏偏紧凑，适合喜欢夜游路线的游客。\n\n【推荐景点】\n成都市天府美术馆、小猪佩奇欢乐乐园(成都店)、资阳市博物馆。\n\n【路线安排】\n第 1 天建议先游览城市核心区域，把交通时间控制在 30 分钟以内。\n第 2 天可以安排特色街区和高评分景点，下午留出休息时间。\n如果时间充足，后续行程可以增加周边景点或夜游活动。\n\n【预算建议】\n人均预算约 500 元，主要包括交通、门票、餐饮和少量伴手礼。\n\n【交