/*Table structure for table `travel_guide_attraction` */

DROP TABLE IF EXISTS `travel_guide_attraction`;

CREATE TABLE `travel_guide_attraction` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL COMMENT '关联时间',
  `attraction_id` bigint NOT NULL COMMENT '关联景点',
  `guide_id` bigint NOT NULL COMMENT '所属攻略',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_guide_attraction` (`guide_id`,`attraction_id`),
  KEY `idx_guide_attr_guide` (`guide_id`),
  KEY `idx_guide_attr_spot` (`attraction_id`),
  CONSTRAINT `travel_guide_attraction_attraction_id_dabea788_fk_attraction_id` FOREIGN KEY (`attraction_id`) REFERENCES `attraction` (`id`),
  CONSTRAINT `travel_guide_attraction_guide_id_5ebf50bc_fk_travel_guide_id` FOREIGN KEY (`guide_id`) REFERENCES `travel_guide` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='旅游攻略关联景点';

/*Data for the table `travel_guide_attraction` */

/*Table structure for table `travel_guide_image` */

DROP TABLE IF EXISTS `travel_guide_image`;

CREATE TABLE `travel_guide_image` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `image` varchar(255) NOT NULL COMMENT '攻略图片',
  `sort_order` smallint unsigned NOT NULL COMMENT '排序序号',
  `created_at` datetime(6) NOT NULL COMMENT '上传时间',
  `guide_id` bigint NOT NULL COMMENT '所属攻略',
  PRIMARY KEY (`id`),
  KEY `idx_guide_image_order` (`guide_id`,`sort_order`),
  CONSTRAINT `travel_guide_image_guide_id_db6b3d1a_fk_travel_guide_id` FOREIGN KEY (`guide_id`) REFERENCES `travel_guide` (`id`),
  CONSTRAINT `travel_guide_image_chk_1` CHECK ((`sort_order` >= 0))
